style.css:
@-moz-document domain("youtube.com") {
/* Progress bar container */
  .ytp-progress-bar-container {
    height: 12px !important;
    background: #111 !important; /* dark pirate background */
    border-radius: 6px !important;
    overflow: hidden !important;
  }

  /* Progress bar fill */
  .ytp-play-progress {
    background: linear-gradient(90deg, #ff0000, #ff9900, #ffd700) !important;
    background-size: 200% 100% !important;
    animation: onepiece-wave 3s linear infinite !important;
    border-radius: 6px !important;
  }

  /* Buffered portion */
  .ytp-load-progress {
    background: rgba(255, 255, 255, 0.2) !important;
  }

  /* Pirate skull marker (using emoji as placeholder) */
  .ytp-scrubber-button::after {
    content: "☠️" !important;
    font-size: 18px !important;
    position: absolute !important;
    top: -22px !important;
    left: -6px !important;
  }

  /* Wave animation */
  @keyframes onepiece-wave {
    0% { background-position: 0% 0; }
    100% { background-position: 200% 0; }
  }
}
